style.css:
@-moz-document domain("youtube.com") {
/* Main background */
  html, body,
  ytd-app {
    background-color: #fff0f6 !important;
    color: #874765 !important;
  }

  /* Top navigation */
  ytd-masthead,
  #masthead-container {
    background: #ffe0ec !important;
  }

  /* Sidebar */
  ytd-mini-guide-renderer,
  ytd-guide-renderer,
  #guide-content {
    background: #ffe8f0 !important;
  }

  /* Video cards */
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-grid-video-renderer {
    border-radius: 18px !important;
  }

  /* Search bar */
  #container.ytd-searchbox {
    background: #fff7fa !important;
    border: 2px solid #f3b6cc !important;
    border-radius: 25px !important;
  }

  /* Search button */
  ytd-searchbox button {
    background: #f7c2d7 !important;
    border-radius: 0 25px 25px 0 !important;
  }

  /* Buttons */
  ytd-button-renderer button,
  yt-button-shape button {
    border-radius: 20px !important;
  }

  /* Subscribe button */
  ytd-subscribe-button-renderer button {
    background: #f4a9c4 !important;
    color: #71334f !important;
    border-radius: 25px !important;
  }

  /* Video progress bar */
  .ytp-play-progress {
    background: #ed91b5 !important;
  }

  .ytp-scrubber-button {
    background: #ed91b5 !important;
  }

  /* Rounded thumbnails */
  ytd-thumbnail,
  yt-image img {
    border-radius: 14px !important;
  }

  /* Hover effects */
  ytd-rich-item-renderer:hover {
    background: #ffe4ee !important;
    border-radius: 18px !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar-thumb {
    background: #efa8c2 !important;
    border-radius: 20px !important;
  }

  ::-webkit-scrollbar-track {
    background: #fff0f6 !important;
  }
}
